// Requires the `run-proto` subcommand (Task 4) and the `reasoning` module
// generated by build.rs (Task 3). Drives the real compiled `cubelang`
// binary as a subprocess over stdin/stdout -- the exact transport Task 5's
// Python client will use -- rather than calling anything in-process, so this
// proves the actual wire behavior end to end, not just the mapping function.
use cubelang::reasoning::{RunRequest, RunResult, run_result};
use prost::Message;
use std::io::{Read, Write};
use std::process::{Command, Stdio};

fn call_proto(req: RunRequest) -> RunResult {
    let exe = env!("CARGO_BIN_EXE_cubelang");
    let mut child = Command::new(exe).arg("run-proto")
        .stdin(Stdio::piped()).stdout(Stdio::piped()).spawn().unwrap();
    let mut buf = Vec::new(); req.encode(&mut buf).unwrap();
    let mut stdin = child.stdin.take().unwrap();
    stdin.write_all(&(buf.len() as u32).to_be_bytes()).unwrap();
    stdin.write_all(&buf).unwrap();
    drop(stdin);
    let mut out = Vec::new();
    child.stdout.take().unwrap().read_to_end(&mut out).unwrap();
    child.wait().unwrap();
    let len = u32::from_be_bytes(out[..4].try_into().unwrap()) as usize;
    RunResult::decode(&out[4..4 + len]).unwrap()
}

#[test]
fn proto_stdio_runs_a_recover_program() {
    let program = r#"
use vsa;
program R implements ISolve {
    public function solve(input: str): str {
        create frame: number;
        bind frame, SUBJECT, "cat";
        bind frame, OBJECT, "mouse";
        return recover(frame, SUBJECT);
    }
}
"#;
    let res = call_proto(RunRequest { program: program.into(), args: vec!["_".into()], fn_name: "solve".into(), answers: vec![], ..Default::default() });
    assert!(res.ok);
    assert!(matches!(res.result, Some(run_result::Result::Symbol(ref s)) if s == "cat"));
    // Task 7 (Feature A, similarity-surfacing): a clean single-pair
    // bind->unbind recovery must surface a high-confidence similarity
    // alongside the symbol, not just the symbol. Empirically ~0.52 here
    // (deterministic: fixed codebook seed + fixed symbol names) -- a
    // 2-pair MAP-Bipolar bundle's recovered-role cosine sim centers near
    // 0.5 by construction (half the dims recover exactly, the other half
    // are a coin flip from cross-talk), so 0.3 is the threshold that
    // actually separates "real recovery" from noise: it's ~3x the <0.1
    // near-orthogonal ceiling this repo's own hypervec.rs tests use, with
    // real headroom below the observed value on the other side.
    assert!(res.similarity.is_some(), "solve's clean recover() must surface Some(similarity)");
    assert!(res.similarity.unwrap() > 0.3,
        "clean bind->unbind recovery should score well above chance/noise, got {:?}", res.similarity);
}

// ── wrong_role / unbound over the wire ──────────────────────────────────────
//
// The test above only exercises the right-role case. Task 5 will assert all
// three M1 control cases (solve -> cat, wrong_role -> mouse, unbound ->
// None) over protobuf, matching `cubbyllm/bridges/programs/reasoning_bridge
// .cube` (CubbyLLM repo) and its `test_reasoning_bridge.py`. Proven here so
// the value-mapping -- especially unbound's oneof-UNSET requirement -- is
// caught now, not discovered broken in Task 5.

/// Mirrors `cubbyllm/bridges/programs/reasoning_bridge.cube` exactly: one
/// frame binds SUBJECT->"cat" and OBJECT->"mouse", and three functions
/// exercise the three M1 control cases (right role, wrong role, never-bound
/// role).
fn reasoning_bridge_program() -> &'static str {
    r#"
use vsa;
program ReasoningBridge implements ISolve {
    public function solve(mention: str): str {
        create frame: number;
        bind frame, SUBJECT, "cat";
        bind frame, OBJECT, "mouse";
        return recover(frame, SUBJECT);
    }

    # control: a different role in the same frame recovers a different filler
    public function wrong_role(): str {
        create frame: number;
        bind frame, SUBJECT, "cat";
        bind frame, OBJECT, "mouse";
        return recover(frame, OBJECT);
    }

    # control: an unbound frame recovers no symbol
    public function unbound(): str {
        create frame: number;
        return recover(frame, SUBJECT);
    }
}
"#
}

#[test]
fn proto_stdio_wrong_role_recovers_mouse_not_cat() {
    let res = call_proto(RunRequest {
        program: reasoning_bridge_program().into(),
        args: vec![],
        fn_name: "wrong_role".into(),
        answers: vec![], ..Default::default() });
    assert!(res.ok, "wrong_role must succeed (ok:true)");
    match res.result {
        Some(run_result::Result::Symbol(ref s)) => assert_eq!(s, "mouse", "wrong-role control must recover a different filler than SUBJECT's"),
        other => panic!("expected Symbol(\"mouse\"), got {:?}", other),
    }
    // Task 7: same as `solve` -- a real, clean recovery (just of the other
    // role in the same frame) must also carry a similarity well clear of
    // noise. Empirically ~0.486 here; see `solve`'s test above for why 0.3,
    // not 0.5, is the right cutoff for a 2-pair bundle recovery.
    assert!(res.similarity.is_some(), "wrong_role's clean recover() must surface Some(similarity)");
    assert!(res.similarity.unwrap() > 0.3,
        "clean bind->unbind recovery should score well above chance/noise, got {:?}", res.similarity);
}

// ── Task 8 (Feature B, verify-before-execute) ───────────────────────────────
//
// `run-proto` now compiles the request FROM SOURCE with `compiler::
// compile_strict`, not the loose `compiler::compile` -- so a `use`-ing
// reasoning program (which can't serialize to `.cubebin` and so only ever
// runs from source) gets the SAME strict verification `compile --strict`
// already gave `.cube` files compiled to disk. These two tests are the
// wire-level red/green pair for that swap: a program that only a strict
// check rejects must now fail over the wire, and the real reasoning-bridge
// shape must keep succeeding exactly as before.

#[test]
fn proto_stdio_strict_violation_returns_ok_false_with_strict_error() {
    // Compiles cleanly under the old loose `compiler::compile` (implements
    // present, `solve` provided, matching ISolve) -- `infer` is a normal
    // statement there. Only `compile_strict`'s `strict_check_stmt` rejects
    // it, since `infer` is a trace-only ext op (`is_trace_only_ext_op`) that
    // never executes value-level semantics under the current VM. This is
    // the same minimal shape `src/compiler.rs`'s own
    // `strict_rejects_trace_only_infer` unit test uses.
    let program = r#"
program Test implements ISolve {
    public function solve(input: str): void {
        infer x;
    }
}
"#;
    let res = call_proto(RunRequest {
        program: program.into(),
        args: vec!["_".into()],
        fn_name: "solve".into(),
        answers: vec![], ..Default::default() });
    assert!(!res.ok, "a strict-violating program must not succeed over run-proto");
    match res.result {
        Some(run_result::Result::Error(ref e)) => {
            assert!(e.to_lowercase().contains("infer"),
                "strict error should name the offending construct (infer): got {}", e);
        }
        other => panic!("expected Error(..) naming the strict violation, got {:?}", other),
    }
    // A compile-time failure happens before the VM ever runs -- there is no
    // recover() call to have produced a similarity, and Task 8's fold-in
    // fix (folded-in Minor from Task 7's review) makes this explicit for
    // every non-ok RunResult, not just this one.
    assert!(res.similarity.is_none(), "a compile-time failure must not carry a similarity");
}

#[test]
fn proto_stdio_reasoning_bridge_solve_still_ok_under_strict_verification() {
    // Companion to the strict-violation test above: strict verification must
    // not break the real path. `reasoning_bridge_program()`'s `solve`
    // mirrors `cubbyllm/bridges/programs/reasoning_bridge.cube` exactly and
    // was confirmed clean under `compile_strict` by investigation before
    // this task started; this proves it end to end over the actual wire,
    // now that `run-proto` runs `compile_strict` on every request.
    let res = call_proto(RunRequest {
        program: reasoning_bridge_program().into(),
        args: vec!["_".into()],
        fn_name: "solve".into(),
        answers: vec![], ..Default::default() });
    assert!(res.ok, "reasoning_bridge's solve must still succeed under strict verification");
    match res.result {
        Some(run_result::Result::Symbol(ref s)) => assert_eq!(s, "cat"),
        other => panic!("expected Symbol(\"cat\"), got {:?}", other),
    }
}

#[test]
fn proto_stdio_unbound_maps_to_unset_oneof_not_symbol_null() {
    let res = call_proto(RunRequest {
        program: reasoning_bridge_program().into(),
        args: vec![],
        fn_name: "unbound".into(),
        answers: vec![], ..Default::default() });
    // recover() legitimately finding no bound filler is a successful run,
    // not an error -- matches M1's JSON path, which reports ok:true with
    // result:null for this same program/fn.
    assert!(res.ok, "unbound must still be ok:true; finding no filler isn't a runtime error");
    // The whole point of this test: the unbound/absent-role case must leave
    // the oneof UNSET (so the Python side decodes `None`, matching M1's JSON
    // `null`) -- NOT a stringified `Symbol("null")`, which would silently
    // break the absent-role control on the Python side (Task 5).
    match res.result {
        None => {}
        Some(other) => panic!(
            "unbound recover() must map to an UNSET oneof (Python None), got {:?}", other
        ),
    }
    // Task 7: no winning match means no similarity either -- `similarity`
    // must be unset (None) exactly when `symbol` is, not e.g. Some(0.0).
    assert!(res.similarity.is_none(),
        "unbound recover() must leave similarity unset too (no winning match), got {:?}", res.similarity);
}


// ── resident process + knowledge_path (2026-09-11) ─────────────────────────
//
// `run-proto` now serves until stdin closes. One spawn, N requests, N
// results, in order -- the shape CubbyLLM's `CubelangSession` relies on.
// Each request still runs on a fresh VM, so results must be independent of
// order: the same program asked three times must answer the same three
// times, and a request carrying `knowledge_path` must ground QUERY against
// that file while a request without it must abstain.

fn call_proto_many(reqs: Vec<RunRequest>) -> Vec<RunResult> {
    let exe = env!("CARGO_BIN_EXE_cubelang");
    let mut child = Command::new(exe).arg("run-proto")
        .stdin(Stdio::piped()).stdout(Stdio::piped()).spawn().unwrap();
    let n = reqs.len();
    let mut stdin = child.stdin.take().unwrap();
    for req in reqs {
        let mut buf = Vec::new(); req.encode(&mut buf).unwrap();
        stdin.write_all(&(buf.len() as u32).to_be_bytes()).unwrap();
        stdin.write_all(&buf).unwrap();
        stdin.flush().unwrap();
    }
    drop(stdin);
    let mut out = Vec::new();
    child.stdout.take().unwrap().read_to_end(&mut out).unwrap();
    let status = child.wait().unwrap();
    assert!(status.success(), "run-proto must exit 0 after a clean EOF, got {:?}", status);
    let mut results = Vec::new();
    let mut at = 0usize;
    while at < out.len() {
        let len = u32::from_be_bytes(out[at..at + 4].try_into().unwrap()) as usize;
        results.push(RunResult::decode(&out[at + 4..at + 4 + len]).unwrap());
        at += 4 + len;
    }
    assert_eq!(results.len(), n, "one RunResult per RunRequest, in order");
    results
}

const GROUND_PROGRAM: &str = r#"
program Ground implements ISolve {
    @external
    public function solve(mention: str): number {
        query mention;
        create ctx : number;
        pop ctx;
        let n = ctx.len();
        create outcome : number;
        assign outcome = 0;
        if (n == 0) { assign outcome = 0; } else { assign outcome = 1; }
        return outcome;
    }
}
"#;

fn symbol_of(r: &RunResult) -> String {
    match &r.result {
        Some(run_result::Result::Symbol(s)) => s.clone(),
        other => panic!("expected Symbol, got {:?}", other),
    }
}

#[test]
fn proto_stdio_serves_many_requests_on_one_process() {
    let program = r#"
use vsa;
program R implements ISolve {
    public function solve(input: str): str {
        create frame: number;
        bind frame, SUBJECT, "cat";
        bind frame, OBJECT, "mouse";
        return recover(frame, SUBJECT);
    }
    public function other(): str {
        create frame: number;
        bind frame, SUBJECT, "cat";
        bind frame, OBJECT, "mouse";
        return recover(frame, OBJECT);
    }
}
"#;
    let mk = |f: &str| RunRequest { program: program.into(), args: vec!["_".into()], fn_name: f.into(), ..Default::default() };
    let res = call_proto_many(vec![mk("solve"), mk("other"), mk("solve")]);
    assert!(res.iter().all(|r| r.ok));
    assert_eq!(symbol_of(&res[0]), "cat");
    assert_eq!(symbol_of(&res[1]), "mouse");
    assert_eq!(symbol_of(&res[2]), "cat");
}

#[test]
fn proto_stdio_knowledge_path_grounds_query_per_request() {
    let dir = std::env::temp_dir().join(format!("cubelang_kp_{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("vocab.jsonl");
    std::fs::write(&path, concat!(
        r#"{"key":"capital","text":"capital","source":"store"}"#, "\n",
        r#"{"key":"country of citizenship","text":"country of citizenship","source":"store"}"#, "\n",
    )).unwrap();
    let kp = path.to_string_lossy().to_string();
    let with = |arg: &str| RunRequest { program: GROUND_PROGRAM.into(), args: vec![arg.into()], fn_name: "solve".into(),
                                         knowledge_path: kp.clone(), ..Default::default() };
    let without = |arg: &str| RunRequest { program: GROUND_PROGRAM.into(), args: vec![arg.into()], fn_name: "solve".into(),
                                            ..Default::default() };
    let res = call_proto_many(vec![
        with("capital"),                                      // known         -> 1
        with("award received by the director of photography"),// unknown      -> 0
        without("capital"),                                   // no knowledge  -> 0 (abstains)
        with("Country Of Citizenship"),                       // normalized    -> 1
        with("capital"),                                      // cache hit     -> 1
    ]);
    assert!(res.iter().all(|r| r.ok), "{:?}", res);
    let got: Vec<String> = res.iter().map(symbol_of).collect();
    assert_eq!(got, vec!["1", "0", "0", "1", "1"]);

    // a missing file is an error on THAT request, and the process keeps serving
    let bad = RunRequest { program: GROUND_PROGRAM.into(), args: vec!["capital".into()], fn_name: "solve".into(),
                           knowledge_path: dir.join("nope.jsonl").to_string_lossy().to_string(), ..Default::default() };
    let res = call_proto_many(vec![bad, with("capital")]);
    assert!(!res[0].ok);
    assert!(matches!(res[0].result, Some(run_result::Result::Error(ref e)) if e.contains("knowledge_path")));
    assert!(res[1].ok && symbol_of(&res[1]) == "1");
    let _ = std::fs::remove_dir_all(&dir);
}
